import type { MetadataRoute } from "next";
import { SITE_URL } from "@/lib/site";

/**
 * robots.txt generated by Next (replaces the previous 404 fall-through).
 *
 * AI-search crawlers (GPTBot, OAI-SearchBot, Claude-SearchBot, PerplexityBot,
 * Googlebot, Bingbot, …) are intentionally NOT blocked — citability in AI
 * answers is wanted. We only disallow non-content surfaces: the API, OAuth
 * flows, authenticated app shells, the session-bound shopping journey, and the
 * infinite-ID receipt verifier (also `noindex` at the page level).
 */
export default function robots(): MetadataRoute.Robots {
  return {
    rules: [
      {
        userAgent: "*",
        allow: ["/", "/about", "/security", "/privacy", "/terms"],
        disallow: [
          "/api/",
          "/connect/",
          "/wallet",
          "/insights",
          "/stack",
          "/rescue",
          "/mandate",
          "/shop",
          "/product/",
          "/checkout",
          "/verify/",
        ],
      },
    ],
    sitemap: `${SITE_URL}/sitemap.xml`,
    host: SITE_URL,
  };
}
